def mark_school_subgroups(apps, schema_editor):
    """Let local admins manage each School's existing Academic Staff and Admin Staff groups"""
    Group = apps.get_model('auth', 'Group')
    School = apps.get_model('loads', 'School')
    GroupSettings = apps.get_model('loads', 'GroupSettings')
    for school in School.objects.all():
        for name in (f"{school.name} Academic Staff", f"{school.name} Admin Staff"):
            for group in Group.objects.filter(name=name):
                GroupSettings.objects.update_or_create(group=group, defaults={'locally_managed': True})


